'use strict';
const CW=1920,CH=1080;
let selection=new Set(),elementClipboard=[],snapEnabled=true,showGrid=false,chatMessages=[],apiKey='',aiModel='gpt-6-astra',aiBusy=false,aiAbort=null,aiProposal=null,chatDraft='',activeAPIUsage=null;
let aiProvider='codex',codexModel='',codexModels=[],codexLoginTimer=null,aiProgress='';
layouts.push('free');layoutNames.free='自由配置';
const elementTypes=['text','image','video','audio','shape','embed','table','chart'];
const shapeTypes=['rectangle','ellipse','line','arrow','triangle'];
const elementDefaults={x:160,y:180,w:640,h:200,rotation:0,opacity:1,locked:false,hidden:false,groupId:'',animation:'none',appearAt:0,href:''};
function element(type='text',props={}){return{id:uid(),type,...elementDefaults,...(type==='text'?{text:'テキストを入力',fontSize:56,fontFamily:'sans-serif',color:deck.theme.foreground,bold:false,italic:false,underline:false,align:'left',vertical:'top',lineHeight:1.4,background:'transparent'}:type==='shape'?{shape:'rectangle',fill:deck.theme.accent,stroke:'#ffffff',strokeWidth:0,radius:0}:['image','video','audio'].includes(type)?{assetId:'',fit:'contain',radius:0,media:{start:0,end:0,volume:1,autoplay:true,loop:false,muted:false}}:type==='embed'?{url:'',media:{start:0,end:0,autoplay:false,muted:false,loop:false,volume:1}}:type==='table'?{rows:[['項目','内容'],['例','説明']],fontSize:32,color:deck.theme.foreground,headerFill:deck.theme.accent}:type==='chart'?{values:[30,70,50],labels:['A','B','C'],color:deck.theme.accent,fontSize:24}:{}),...props};}
function freeFromTemplate(s){if(s.elements)return s;const el=[];const title=(x,y,w,h,fontSize)=>el.push(element('text',{text:s.title,x,y,w,h,fontSize,bold:true}));const text=(content,x,y,w,h,fontSize=40)=>el.push(element('text',{text:content,x,y,w,h,fontSize}));
 if(s.eyebrow)el.push(element('text',{text:s.eyebrow,x:145,y:85,w:1630,h:55,fontSize:24,color:deck.theme.accent}));
 if(s.layout==='media'){if(s.assetId){const a=deck.assets.find(a=>a.id===s.assetId);if(a)el.push(element(a.type,{assetId:s.assetId,x:0,y:0,w:CW,h:CH,media:structuredClone(s.media),fit:s.media?.fit||'contain'}));}title(145,790,1630,180,72);}
 else if(s.layout==='split'){title(145,200,760,230,72);text(s.body,145,440,760,430);if(s.assetId){const a=deck.assets.find(a=>a.id===s.assetId);if(a)el.push(element(a.type,{assetId:s.assetId,x:1010,y:200,w:760,h:680,media:structuredClone(s.media)}));}}
 else if(s.layout==='comparison'){title(145,200,1630,170,76);el.push(element('shape',{x:145,y:425,w:770,h:460,fill:'#26303e'}));el.push(element('shape',{x:1000,y:425,w:770,h:460,fill:'#26303e'}));text(s.leftTitle,185,465,690,85,52);text(s.leftBody,185,570,690,290,36);text(s.rightTitle,1040,465,690,85,52);text(s.rightBody,1040,570,690,290,36);}
 else{title(145,s.layout==='title'?300:200,1630,s.layout==='title'?310:250,s.layout==='title'?110:86);text(s.body,145,s.layout==='title'?660:500,1630,380,s.layout==='title'?42:40);}
 if(s.source||deck.author)el.push(element('text',{text:s.source||deck.author,x:145,y:1000,w:1500,h:35,fontSize:20,opacity:.55}));s.elements=el;s.layout='free';return s;}
function ensureFree(){return freeFromTemplate(current());}
function selectedElements(){return(current().elements||[]).filter(e=>selection.has(e.id));}
globalThis.studioHasSelection=()=>selection.size>0;
function cleanSelection(){const ids=new Set((current().elements||[]).map(e=>e.id));selection=new Set([...selection].filter(id=>ids.has(id)));}
function selectElement(id,add=false){if(!add)selection.clear();if(add&&selection.has(id))selection.delete(id);else{selection.add(id);const el=current().elements?.find(e=>e.id===id);if(el?.groupId)current().elements.filter(e=>e.groupId===el.groupId).forEach(e=>selection.add(e.id));}renderSelection();renderInspector();if(panel==='layers')renderSidebar();}
function selectedMain(){return selectedElements()[0];}
const legacyValidate=validate;
validate=function(d){legacyValidate(d);for(const s of d.slides){if(s.background&&!/^#[\da-f]{6}$/i.test(s.background))throw Error('スライドの背景はHEX色で指定してください。');if(s.elements!==undefined){if(!Array.isArray(s.elements)||s.elements.length>1000)throw Error('要素はスライドごとに1000個までです。');const ids=new Set();for(const e of s.elements){if(!e||typeof e.id!=='string'||ids.has(e.id)||!elementTypes.includes(e.type))throw Error('要素のIDまたは種類を確認してください。');ids.add(e.id);for(const k of ['x','y','w','h'])if(!Number.isFinite(e[k]))throw Error('位置・サイズは数値で指定してください。');if(e.w<1||e.h<1||e.w>20000||e.h>20000||Math.abs(e.x)>20000||Math.abs(e.y)>20000)throw Error('要素の位置・サイズが範囲外です。');for(const k of ['rotation','opacity','fontSize','strokeWidth','radius','lineHeight'])if(e[k]!==undefined&&!Number.isFinite(e[k]))throw Error(k+'は数値で指定してください。');if(e.appearAt!==undefined&&(!Number.isInteger(e.appearAt)||e.appearAt<0||e.appearAt>100))throw Error('クリック表示は0〜100の整数です。');if(e.opacity!==undefined&&(e.opacity<0||e.opacity>1))throw Error('透明度は0〜1です。');if(e.fontSize!==undefined&&(e.fontSize<1||e.fontSize>1000))throw Error('文字サイズは1〜1000です。');for(const k of ['color','fill','stroke','background','headerFill'])if(e[k]!==undefined&&!/^(#[\da-f]{3,8}|transparent)$/i.test(e[k]))throw Error('色はHEXまたはtransparentにしてください。');if(e.type==='text'){if(typeof e.text!=='string')throw Error('テキスト要素にtextが必要です。');validateTextRuns(e);}if(e.type==='shape'&&!shapeTypes.includes(e.shape))throw Error('図形の種類が不正です。');if(e.type==='embed')parseEmbed(e.url);if(e.href&&!/^https?:\/\//i.test(e.href))throw Error('リンクはhttp(s) URLのみです。');if(e.media){for(const k of ['start','end','volume'])if(e.media[k]!==undefined&&(!Number.isFinite(e.media[k])||e.media[k]<0))throw Error('再生設定を確認してください。');if(e.media.volume>1||e.media.end>0&&e.media.end<=e.media.start)throw Error('音量または再生範囲を確認してください。');}if(e.type==='table'&&(!Array.isArray(e.rows)||e.rows.length>50||e.rows.some(row=>!Array.isArray(row)||row.length>20||row.some(c=>typeof c!=='string'))))throw Error('表は50行×20列以内の文字列配列です。');if(e.type==='chart'&&(!Array.isArray(e.values)||!e.values.length||e.values.length>50||e.values.some(v=>!Number.isFinite(v)||v<0)||!Array.isArray(e.labels)||e.labels.some(l=>typeof l!=='string')))throw Error('グラフの数値・ラベルを確認してください。');}}}return d;};
function parseEmbed(input){const raw=String(input||'').trim();let url;try{url=new URL(raw);}catch{throw Error('YouTubeまたはVimeoの動画URLを入力してください。');}if(!['https:','http:'].includes(url.protocol))throw Error('埋め込みURLを確認してください。');const host=url.hostname.toLowerCase().replace(/^www\./,'');let id,provider,hash='';if(['youtube.com','m.youtube.com','youtube-nocookie.com'].includes(host)){id=url.searchParams.get('v')||url.pathname.match(/^\/(?:embed|shorts|live)\/([\w-]{11})/)?.[1];provider='youtube';}else if(host==='youtu.be'){id=url.pathname.slice(1).split('/')[0];provider='youtube';}else if(['vimeo.com','player.vimeo.com'].includes(host)){const parts=url.pathname.split('/').filter(Boolean);id=[...parts].reverse().find(p=>/^\d+$/.test(p));provider='vimeo';hash=url.searchParams.get('h')||parts.find(p=>/^[a-f0-9]{8,}$/.test(p)&&p!==id)||'';}if(provider==='youtube'&&!/^[\w-]{11}$/.test(id||'')||provider==='vimeo'&&!/^\d+$/.test(id||'')||!provider)throw Error('動画IDを取得できません。YouTubeまたはVimeoの動画URLを指定してください。');return{provider,id,hash};}
function embedURL(e,play=false){const p=parseEmbed(e.url),m=e.media||{};const u=new URL(p.provider==='youtube'?`https://www.youtube-nocookie.com/embed/${p.id}`:`https://player.vimeo.com/video/${p.id}`);if(p.hash)u.searchParams.set('h',p.hash);u.searchParams.set('autoplay',play&&m.autoplay?'1':'0');u.searchParams.set(p.provider==='youtube'?'mute':'muted',m.muted?'1':'0');if(p.provider==='youtube'){u.searchParams.set('start',String(Math.floor(m.start||0)));if(m.end>0)u.searchParams.set('end',String(Math.floor(m.end)));u.searchParams.set('enablejsapi','1');if(/^https?:/.test(location.protocol||''))u.searchParams.set('origin',location.origin);if(m.loop){u.searchParams.set('loop','1');u.searchParams.set('playlist',p.id);}}else{u.searchParams.set('loop',m.loop?'1':'0');if(m.start)u.hash='t='+m.start+'s';}return u.href;}
function textStyle(e){return`font-size:${(e.fontSize||48)/CW*100}cqw;font-family:${e.fontFamily==='serif'?'Georgia,serif':e.fontFamily==='mono'?'ui-monospace,monospace':'Inter,-apple-system,BlinkMacSystemFont,sans-serif'};font-weight:${e.bold?700:400};font-style:${e.italic?'italic':'normal'};text-decoration:${e.underline?'underline':'none'};text-align:${['left','center','right','justify'].includes(e.align)?e.align:'left'};line-height:${e.lineHeight||1.4};color:${e.color||deck.theme.foreground};background:${e.background||'transparent'};justify-content:${e.vertical==='middle'?'center':e.vertical==='bottom'?'flex-end':'flex-start'};`;}
function elementHTML(e,assets,{play=false,edit=false,step=999}={}){if(e.hidden)return'';let content='';const m=e.media||{};if(e.type==='text')content=`<div class="element-text" style="${textStyle(e)}">${richTextHTML(e)}</div>`;
else if(['image','video','audio'].includes(e.type)){const asset=assets.find(a=>a.id===e.assetId);const src=asset?safeSrc(asset.src):'';if(!src)content='<div class="element-placeholder">素材を選択</div>';else if(e.type==='image')content=`<img src="${esc(src)}" alt="${esc(asset.name)}" draggable="false" style="object-fit:${e.fit==='cover'?'cover':'contain'};border-radius:${(e.radius||0)/CW*100}cqw">`;else if(e.type==='video')content=`<video src="${esc(src)}" playsinline ${m.muted?'muted':''} ${play?'controls':''} preload="metadata" data-element-media="${esc(e.id)}" style="object-fit:${e.fit==='cover'?'cover':'contain'};border-radius:${(e.radius||0)/CW*100}cqw"></video>`;else content=`<audio src="${esc(src)}" controls ${m.muted?'muted':''} preload="metadata" data-element-media="${esc(e.id)}"></audio>`;}
else if(e.type==='embed'){if(play&&(e.appearAt||0)<=step)content=`<iframe src="${esc(embedURL(e,true))}" title="${esc(e.name||'埋め込み動画')}" allow="autoplay; fullscreen; picture-in-picture; encrypted-media" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;else{const p=parseEmbed(e.url);content=`<div class="embed-placeholder"><span>▶</span><strong>${p.provider==='youtube'?'YouTube':'Vimeo'}</strong><small>${esc(p.id)}</small><small>「素材再生」または発表時に読み込み</small></div>`;}}
else if(e.type==='shape'){if(e.shape==='line'||e.shape==='arrow')content=`<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="${e.shape}"><line x1="0" y1="50" x2="${e.shape==='arrow'?90:100}" y2="50" stroke="${e.strokeWidth?e.stroke:e.fill}" stroke-width="${Math.max(1,e.strokeWidth||3)}" vector-effect="non-scaling-stroke"/>${e.shape==='arrow'?`<path d="M80 30 L100 50 L80 70" fill="none" stroke="${e.strokeWidth?e.stroke:e.fill}" stroke-width="${Math.max(1,e.strokeWidth||3)}" vector-effect="non-scaling-stroke"/>`:''}</svg>`;else content=`<div class="element-shape" style="background:${e.fill};border:${e.strokeWidth||0}px solid ${e.stroke||'transparent'};border-radius:${e.shape==='ellipse'?'50%':(e.radius||0)/CW*100+'cqw'};${e.shape==='triangle'?'clip-path:polygon(50% 0,100% 100%,0 100%);':''}"></div>`;}
else if(e.type==='table'){content=`<table class="element-table" style="font-size:${(e.fontSize||32)/CW*100}cqw;color:${e.color||deck.theme.foreground}">${(e.rows||[]).map((r,i)=>`<tr ${!i?`style="background:${e.headerFill||deck.theme.accent};color:#111318"`:''}>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table>`;}
else if(e.type==='chart'){const max=Math.max(1,...e.values);content=`<div class="element-chart" style="font-size:${(e.fontSize||24)/CW*100}cqw">${e.values.map((v,i)=>`<div class="chart-column"><span>${v}</span><div class="chart-bar" style="height:${v/max*80}%;background:${e.color||deck.theme.accent}"></div><small>${esc(e.labels[i]||'')}</small></div>`).join('')}</div>`;}
const appearance=e.animation&&e.animation!=='none'?` data-animation="${esc(e.animation)}"` :'';return`<div class="canvas-element ${edit?'editable':''} ${e.locked?'locked':''}" data-element="${esc(e.id)}" data-appear-at="${e.appearAt||0}"${appearance} style="left:${e.x/CW*100}%;top:${e.y/CH*100}%;width:${e.w/CW*100}%;height:${e.h/CH*100}%;transform:rotate(${e.rotation||0}deg);opacity:${e.opacity??1};visibility:${(e.appearAt||0)>step?'hidden':'visible'};">${content}${!edit&&e.href?`<a class="element-link" href="${esc(e.href)}" target="_blank" rel="noopener noreferrer" aria-label="リンクを開く"></a>`:''}</div>`;}
const templateHTML=slideHTML;
slideHTML=function(s,options={}){if(!s.elements)return templateHTML(s,options);const t=deck.theme;return`<article class="slide free-slide ${s.transition==='fade'?'transition-fade':''}" style="--slide-bg:${s.background||t.background};--slide-fg:${t.foreground};--slide-accent:${t.accent}">${s.elements.map(e=>elementHTML(e,options.assets||deck.assets,options)).join('')}</article>`;};
const originalRenderStage=renderStage;
renderStage=function(){cleanSelection();originalRenderStage();if(current().elements){const stage=$('#stage');stage.classList.toggle('show-grid',showGrid);stage.querySelectorAll('.canvas-element').forEach(el=>el.classList.add('editable'));renderSelection();}if(presenting)applyAnimations($('#presentation-stage'));};
function renderSelection(){const stage=$('#stage');if(!stage)return;stage.querySelectorAll('.selection-handle').forEach(h=>h.remove());stage.querySelectorAll('[data-element]').forEach(el=>{const selected=selection.has(el.dataset.element);el.classList.toggle('selected',selected);if(selected&&!current().elements.find(e=>e.id===el.dataset.element)?.locked){for(const direction of ['nw','n','ne','e','se','s','sw','w']){const handle=document.createElement('i');handle.className='selection-handle handle-'+direction;handle.dataset.handle=direction;el.append(handle);}if(current().elements.find(e=>e.id===el.dataset.element)?.type==='text'){const move=document.createElement('i');move.className='selection-handle text-move-handle';move.textContent='↔';move.title='ドラッグしてテキストボックスを移動';move.setAttribute('aria-label','テキストボックスを移動');el.append(move);}}});}
function applyAnimations(root){if(!root)return;root.querySelectorAll('[data-animation]').forEach(el=>{el.classList.add('animate-'+el.dataset.animation);});}
const legacySetupMedia=setupMedia;
setupMedia=function(root,s,play){if(!s.elements)return legacySetupMedia(root,s,play);root.querySelectorAll('video,audio').forEach(el=>{const e=s.elements.find(e=>e.id===el.dataset.elementMedia);if(!e||(presenting&&(e.appearAt||0)>fragmentStep))return;const m=e.media||{};el.volume=Math.max(0,Math.min(1,m.volume??1));const start=m.start||0,end=m.end||0;const seek=()=>{if(start<el.duration)el.currentTime=start;};if(el.readyState>=1)seek();else el.addEventListener('loadedmetadata',seek,{once:true});el.addEventListener('timeupdate',()=>{if(end>start&&el.currentTime>=end){if(m.loop){el.currentTime=start;el.play().catch(()=>{});}else el.pause();}});el.addEventListener('ended',()=>{if(m.loop){el.currentTime=start;el.play().catch(()=>{});}});el.addEventListener('error',()=>log('素材を再生できません。形式・URLを確認してください。','warn'),{once:true});if(play&&m.autoplay)el.play().catch(()=>toast('素材の再生ボタンを押してください'));});applyAnimations(root);};
const templateInspector=renderInspector;
function ef(label,key,value,type='text',extra=''){return`<div class="field"><label>${label}</label>${type==='textarea'?`<textarea data-element-field="${key}" ${extra}>${esc(value)}</textarea>`:`<input type="${type}" data-element-field="${key}" value="${esc(value)}" ${extra}>`}</div>`;}
function es(label,key,options,value){return`<div class="field"><label>${label}</label><select data-element-field="${key}">${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></div>`;}
function elementInspector(e){const m=e.media||{};return`<section class="inspector-section"><h3>ELEMENT / ${e.type.toUpperCase()} ${selection.size>1?'· '+selection.size+' selected':''}</h3>${ef('名前','name',e.name||'')}<div class="field-row">${ef('X','x',e.x,'number')}${ef('Y','y',e.y,'number')}${ef('幅','w',e.w,'number','min="1"')}${ef('高さ','h',e.h,'number','min="1"')}${ef('回転 / °','rotation',e.rotation||0,'number')}${ef('透明度','opacity',e.opacity??1,'number','min="0" max="1" step="0.05"')}</div><div class="button-row"><button data-action="align-left">左</button><button data-action="align-center">中央</button><button data-action="align-right">右</button><button data-action="align-top">上</button><button data-action="align-middle">中</button><button data-action="align-bottom">下</button><button data-action="distribute-x">横に均等</button><button data-action="distribute-y">縦に均等</button></div><div class="button-row" style="margin-top:10px"><button data-action="element-front">最前面</button><button data-action="element-back">最背面</button><button data-action="element-forward">前へ</button><button data-action="element-backward">後ろへ</button><button data-action="element-duplicate">複製</button><button class="danger" data-action="element-delete">削除</button></div><label class="check"><input type="checkbox" data-element-field="locked" ${e.locked?'checked':''}>位置をロック</label><label class="check"><input type="checkbox" data-element-field="hidden" ${e.hidden?'checked':''}>非表示</label><div class="button-row"><button data-action="group">グループ</button><button data-action="ungroup">解除</button></div></section>
${e.type==='text'?`<section class="inspector-section"><h3>TEXT</h3>${ef('内容','text',e.text,'textarea')}${ef('文字サイズ / px','fontSize',e.fontSize,'number','min="1" max="1000"')}${es('書体','fontFamily',[['sans-serif','Sans'],['serif','Serif'],['mono','Monospace']],e.fontFamily)}<div class="button-row">${['bold','italic','underline'].map(k=>`<button class="${e[k]?'selected-format':''}" data-format="${k}">${{bold:'B 太字',italic:'I 斜体',underline:'U 下線'}[k]}</button>`).join('')}</div>${ef('文字色','color',e.color,'color')}${ef('背景 / HEXかtransparent','background',e.background||'transparent')}${es('横位置','align',[['left','左'],['center','中央'],['right','右'],['justify','均等']],e.align)}${es('縦位置','vertical',[['top','上'],['middle','中央'],['bottom','下']],e.vertical)}${ef('行間','lineHeight',e.lineHeight,'number','min="0.5" step="0.1"')}</section>`:''}
${['image','video','audio'].includes(e.type)?`<section class="inspector-section"><h3>ASSET</h3><div class="field"><label>素材</label><select data-element-field="assetId"><option value="">未設定</option>${deck.assets.filter(a=>a.type===e.type).map(a=>`<option value="${esc(a.id)}" ${a.id===e.assetId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div>${es('収まり','fit',[['contain','全体を表示'],['cover','枠を埋める']],e.fit)}${ef('角丸','radius',e.radius||0,'number','min="0"')}<button data-action="crop-center">中央でトリミング</button><button data-action="aspect-ratio">素材の比率に合わせる</button></section>`:''}
${e.type==='embed'?`<section class="inspector-section"><h3>YOUTUBE / VIMEO</h3>${ef('動画URL','url',e.url)}<p class="muted" style="font-size:12px;line-height:1.7">埋め込みを許可している動画のみ再生できます。ネット接続が必要です。</p></section>`:''}
${['video','audio','embed'].includes(e.type)?`<section class="inspector-section"><h3>PLAYBACK</h3><div class="field-row">${ef('開始 / 秒','media.start',m.start||0,'number','min="0"')}${ef('終了 / 0=末尾','media.end',m.end||0,'number','min="0"')}</div>${e.type!=='embed'?ef('音量 / 0〜1','media.volume',m.volume??1,'number','min="0" max="1" step="0.05"'):''}${['autoplay','loop','muted'].map(k=>`<label class="check"><input type="checkbox" data-element-field="media.${k}" ${m[k]?'checked':''}>${{autoplay:'自動再生',loop:'ループ',muted:'ミュート'}[k]}</label>`).join('')}</section>`:''}
${e.type==='shape'?`<section class="inspector-section"><h3>SHAPE</h3>${es('形','shape',shapeTypes.map(s=>[s,{rectangle:'四角',ellipse:'円',line:'線',arrow:'矢印',triangle:'三角'}[s]]),e.shape)}${ef('塗り','fill',e.fill,'color')}${ef('線色','stroke',e.stroke,'color')}${ef('線幅','strokeWidth',e.strokeWidth,'number','min="0"')}${ef('角丸','radius',e.radius||0,'number','min="0"')}</section>`:''}
${e.type==='table'?`<section class="inspector-section"><h3>TABLE</h3>${ef('行ごとに改行、列はタブ区切り','tableText',e.rows.map(r=>r.join('\t')).join('\n'),'textarea')}${ef('文字サイズ','fontSize',e.fontSize,'number','min="1"')}${ef('文字色','color',e.color,'color')}${ef('ヘッダー色','headerFill',e.headerFill,'color')}</section>`:''}
${e.type==='chart'?`<section class="inspector-section"><h3>BAR CHART</h3>${ef('数値 / カンマ区切り','chartValues',e.values.join(', '))}${ef('ラベル / カンマ区切り','chartLabels',e.labels.join(', '))}${ef('色','color',e.color,'color')}</section>`:''}
<section class="inspector-section"><h3>ANIMATION / LINK</h3>${es('表示時の効果','animation',[['none','なし'],['fade','フェード'],['rise','下から表示'],['zoom','拡大']],e.animation||'none')}${ef('クリック表示 / 0=即時','appearAt',e.appearAt||0,'number','min="0" max="100" step="1"')}${ef('クリック時のリンク','href',e.href||'')}</section>`;}
renderInspector=function(){cleanSelection();const e=selectedMain();if(e){$('#inspector-body').innerHTML=elementInspector(e);return;}if(!current().elements){templateInspector();return;}const s=current();$('#inspector-body').innerHTML=`<section class="inspector-section"><h3>FREE CANVAS</h3><p class="muted" style="line-height:1.8">要素をクリックして編集。ダブルクリックで文字入力。Shift＋クリックで複数選択。</p>${field('スライド名','title',s.title)}${field('背景色','background',s.background||deck.theme.background,'color')}<div class="field"><label>切り替え</label><select data-field="transition"><option value="none">なし</option><option value="fade" ${s.transition==='fade'?'selected':''}>フェード</option></select></div>${field('TouchDesigner Cue','cue',s.cue||'')}<div class="button-row"><button data-action="duplicate">スライド複製</button><button class="danger" data-action="delete-slide">削除</button></div></section><section class="inspector-section"><h3>THEME</h3>${field('背景','theme.background',deck.theme.background,'color')}${field('文字','theme.foreground',deck.theme.foreground,'color')}${field('アクセント','theme.accent',deck.theme.accent,'color')}${field('発表者','author',deck.author||'')}</section><section class="inspector-section"><h3>CANVAS / 1920 × 1080</h3><button data-action="toggle-grid">グリッド ${showGrid?'ON':'OFF'}</button><button data-action="toggle-snap">スナップ ${snapEnabled?'ON':'OFF'}</button><button data-action="select-all-elements">全要素を選択</button><button data-action="template-menu">テンプレートを追加</button></section>`;};
function renderLayers(){return`<div class="sidebar-footer"><button data-action="add-text">＋ テキスト</button><button data-action="select-all-elements">全選択</button></div>${(current().elements||[]).slice().reverse().map(e=>`<div class="layer-row ${selection.has(e.id)?'active':''}" data-layer="${esc(e.id)}"><span>${{text:'T',image:'▧',video:'▶',audio:'♫',shape:'□',embed:'↗',table:'▦',chart:'▥'}[e.type]}</span><strong>${esc(e.name||e.text?.slice(0,25)||e.type)}</strong><button data-layer-lock="${esc(e.id)}" title="ロック">${e.locked?'🔒':'◇'}</button><button data-layer-hide="${esc(e.id)}" title="表示切替">${e.hidden?'○':'●'}</button></div>`).join('')||'<div class="empty">要素を追加するか「自由配置に変換」を押してください。</div>'}`;}
