function addElement(type,props={}){snapshot();ensureFree();const e=element(type,props);current().elements.push(e);selection=new Set([e.id]);changed();return e;}
function mutateSelected(fn){const elements=selectedElements();if(!elements.length)return;snapshot();fn(elements,current().elements);changed();}
function addAssetElement(id){const a=deck.assets.find(a=>a.id===id);if(!a)return;addElement(a.type,{assetId:id,x:260,y:160,w:a.type==='audio'?1000:960,h:a.type==='audio'?160:540,name:a.name});}
function duplicateElements(){mutateSelected((els,all)=>{const copied=els.map(e=>({...structuredClone(e),id:uid(),x:e.x+24,y:e.y+24,groupId:''}));all.push(...copied);selection=new Set(copied.map(e=>e.id));});}
function deleteElements(){if(!selection.size)return;snapshot();current().elements=current().elements.filter(e=>!selection.has(e.id));selection.clear();changed();}
function alignElements(mode){mutateSelected(els=>{const movable=els.filter(e=>!e.locked);if(!movable.length)return;const left=Math.min(...movable.map(e=>e.x)),right=Math.max(...movable.map(e=>e.x+e.w)),top=Math.min(...movable.map(e=>e.y)),bottom=Math.max(...movable.map(e=>e.y+e.h));for(const e of movable){if(mode==='left')e.x=movable.length===1?0:left;if(mode==='right')e.x=(movable.length===1?CW:right)-e.w;if(mode==='center')e.x=((movable.length===1?0:left)+(movable.length===1?CW:right))/2-e.w/2;if(mode==='top')e.y=movable.length===1?0:top;if(mode==='bottom')e.y=(movable.length===1?CH:bottom)-e.h;if(mode==='middle')e.y=((movable.length===1?0:top)+(movable.length===1?CH:bottom))/2-e.h/2;}});}
function distribute(axis){mutateSelected(els=>{const movable=els.filter(e=>!e.locked).sort((a,b)=>a[axis]-b[axis]);if(movable.length<3)return;const dimension=axis==='x'?'w':'h',first=movable[0][axis],last=movable.at(-1)[axis]+movable.at(-1)[dimension],sum=movable.reduce((v,e)=>v+e[dimension],0),gap=(last-first-sum)/(movable.length-1);let cursor=first;movable.forEach(e=>{e[axis]=cursor;cursor+=e[dimension]+gap;});});}
function reorderElements(direction){mutateSelected((els,all)=>{const selected=all.filter(e=>selection.has(e.id)),other=all.filter(e=>!selection.has(e.id));if(direction==='front')current().elements=[...other,...selected];else if(direction==='back')current().elements=[...selected,...other];else if(direction==='forward'){for(let i=all.length-2;i>=0;i--)if(selection.has(all[i].id)&&!selection.has(all[i+1].id))[all[i],all[i+1]]=[all[i+1],all[i]];}else{for(let i=1;i<all.length;i++)if(selection.has(all[i].id)&&!selection.has(all[i-1].id))[all[i],all[i-1]]=[all[i-1],all[i]];}});}
function changeElementField(key,value){const proposal=structuredClone(deck);const slide=proposal.slides[index];for(const e of slide.elements.filter(e=>selection.has(e.id))){if(key==='tableText')e.rows=value.split('\n').map(r=>r.split('\t'));else if(key==='chartValues')e.values=value.split(',').map(v=>Number(v.trim()));else if(key==='chartLabels')e.labels=value.split(',').map(v=>v.trim());else if(key.startsWith('media.'))e.media={...e.media,[key.slice(6)]:value};else if(e.type==='text')updateTextElement(e,{[key]:value});else e[key]=value;}try{validate(proposal);snapshot();deck=proposal;changed();}catch(err){toast(err.message);renderInspector();}}
