function templateDialog(){showModal('<h2>テンプレートを追加</h2>'+[['title','タイトル'],['split','画像＋文章'],['comparison','比較'],['quote','引用・問い'],['text','文章']].map(([layout,name])=>`<button class="export-option" data-template="${layout}"><strong>${name}</strong></button>`).join('')+'<div class="modal-actions"><button data-action="close-modal">閉じる</button></div>');}
Object.assign(actions,{'add-text':()=>addElement('text'),'add-shape':()=>addElement('shape',{x:500,y:250,w:600,h:350}),'add-table':()=>addElement('table',{w:1200,h:500}),'add-chart':()=>addElement('chart',{w:1100,h:650}),'add-embed':embedDialog,'insert-embed'(){const url=$('#embed-url').value.trim();parseEmbed(url);addElement('embed',{url,x:360,y:200,w:1200,h:675});closeModal();},'convert-free'(){snapshot();ensureFree();changed();toast('自由配置に変換しました');},'element-delete':deleteElements,'element-duplicate':duplicateElements,'element-front':()=>reorderElements('front'),'element-back':()=>reorderElements('back'),'element-forward':()=>reorderElements('forward'),'element-backward':()=>reorderElements('backward'),'group'(){if(selection.size<2)return;const group=uid();mutateSelected(els=>els.forEach(e=>e.groupId=group));},'ungroup':()=>mutateSelected(els=>els.forEach(e=>e.groupId='')),'toggle-grid'(){showGrid=!showGrid;renderStage();renderInspector();},'toggle-snap'(){snapEnabled=!snapEnabled;renderInspector();},'select-all-elements'(){selection=new Set((current().elements||[]).map(e=>e.id));renderSelection();renderInspector();},'crop-center':()=>mutateSelected(els=>els.forEach(e=>e.fit='cover')),'aspect-ratio'(){const e=selectedMain(),a=deck.assets.find(a=>a.id===e?.assetId);if(!a)return;const media=a.type==='image'?new Image():document.createElement('video');const done=()=>{const w=media.naturalWidth||media.videoWidth,h=media.naturalHeight||media.videoHeight;if(w&&h)mutateSelected(els=>els.forEach(el=>el.h=el.w*h/w));};if(a.type==='image')media.onload=done;else media.onloadedmetadata=done;media.src=a.src;},'template-menu':templateDialog});
for(const mode of ['left','center','right','top','middle','bottom'])actions['align-'+mode]=()=>alignElements(mode);
actions['distribute-x']=()=>distribute('x');actions['distribute-y']=()=>distribute('y');
const baseAddSlide=actions.add;actions.add=()=>{baseAddSlide();current().elements=[];current().layout='free';current().title='新しいスライド';selection.clear();changed();};
