function mountEditorTools(){const toolbar=document.createElement('div');toolbar.className='insert-toolbar';toolbar.innerHTML='<button data-action="add-text">T テキスト</button><button data-action="upload">▧ 素材</button><button data-action="add-embed">▶ YouTube / Vimeo</button><button data-action="add-shape">□ 図形</button><button data-action="add-table">▦ 表</button><button data-action="add-chart">▥ グラフ</button><button data-action="convert-free" title="既存レイアウトを自由配置に変換">自由配置</button><div class="grow"></div><button data-action="toggle-grid" title="グリッド">⊞</button><button data-action="template-menu">テンプレート</button>';$('.canvas-toolbar').after(toolbar);const layer=document.createElement('button');layer.title='レイヤー';layer.dataset.panel='layers';layer.textContent='▱';$('.activity').insertBefore(layer,$('.activity .grow'));const menu=document.createElement('button');menu.dataset.action='show-chat';menu.className='ai-open';menu.textContent='✦ AIと作成';$('.header-actions').insertBefore(menu,$('.header-actions .primary'));}
