document.addEventListener('change',ev=>{const e=ev.target,key=e.dataset.elementField;if(!key)return;const value=e.type==='checkbox'?e.checked:e.type==='number'||e.type==='range'?Number(e.value):e.value;changeElementField(key,value);});
document.addEventListener('click',ev=>{const fmt=ev.target.closest('[data-format]');if(fmt){changeElementField(fmt.dataset.format,!selectedMain()?.[fmt.dataset.format]);return;}const row=ev.target.closest('[data-layer]');if(row){const lock=ev.target.closest('[data-layer-lock]'),hide=ev.target.closest('[data-layer-hide]');if(lock||hide){const e=current().elements.find(e=>e.id===(lock?.dataset.layerLock||hide.dataset.layerHide));snapshot();e[lock?'locked':'hidden']=!e[lock?'locked':'hidden'];changed();}else selectElement(row.dataset.layer,ev.shiftKey);return;}const template=ev.target.closest('[data-template]');if(template){snapshot();const s=newSlide(template.dataset.template);s.title='新しいスライド';deck.slides.splice(index+1,0,s);index++;freeFromTemplate(s);selection.clear();changed();closeModal();}});
