const templateAdvance=advance;
function revealPresentationStep(){const root=$('#presentation-stage');for(const e of current().elements){const box=root.querySelector(`[data-element="${CSS.escape(e.id)}"]`);if(!box)continue;const showing=(e.appearAt||0)<=fragmentStep,wasVisible=box.style.visibility!=='hidden';box.style.visibility=showing?'visible':'hidden';if(showing&&!wasVisible){if(e.type==='embed'){const f=document.createElement('iframe');f.src=embedURL(e,true);f.title=e.name||'埋め込み動画';f.allow='autoplay; fullscreen; picture-in-picture; encrypted-media';f.allowFullscreen=true;f.referrerPolicy='strict-origin-when-cross-origin';box.innerHTML='';box.append(f);}else if(['video','audio'].includes(e.type))setupMedia(box,current(),true);applyAnimations(box.parentNode);}else if(!showing&&wasVisible){box.querySelectorAll('video,audio').forEach(m=>m.pause());box.querySelectorAll('iframe').forEach(f=>f.remove());}}broadcast();}
