let chatAttachments=[],attachmentBusy=false;
function allChatAttachmentIds(){return [...new Set([...chatMessages.flatMap(m=>(m.attachments||[]).map(a=>a.id)),...chatAttachments.map(a=>a.id)])];}
function chatAttachmentHTML(files,editable=false){return files.length?`<div class="chat-attachments">${files.map(a=>`<div class="chat-attachment"><span>${a.kind==='image'?'▧':'▤'}</span><span class="attachment-name" title="${esc(a.name)}">${esc(a.name)}<small>${(a.size/1024).toFixed(0)} KB${a.characters?' · '+a.characters+'文字':''}</small></span>${editable&&a.kind==='image'?`<button data-attachment-asset="${esc(a.id)}" title="スライドの素材として追加">素材へ</button>`:''}${editable?`<button data-remove-chat-attachment="${esc(a.id)}" aria-label="${esc(a.name)}を添付から外す">×</button>`:''}</div>`).join('')}</div>`:'';}
function fileDataURL(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('ファイルを読み込めません: '+file.name));reader.readAsDataURL(file);});}
async function addChatFiles(files){
 if(aiBusy||attachmentBusy){toast('処理が終わってから添付してください');return;}
 if(!['localhost','127.0.0.1'].includes(location.hostname)||!/^http/.test(location.protocol)){toast('添付はローカルサーバー版で利用できます');return;}
 if(!bridgeToken){aiSettings();toast('先にBridge tokenを設定してください');return;}
 if(allChatAttachmentIds().length+files.length>8){toast('1つの会話への添付は8件までです。不要な添付を外すかチャットをクリアしてください');return;}
 attachmentBusy=true;renderChatSidebar();
 try{for(const file of files){
  try{
   if(file.size>10*1024*1024)throw Error('1件10MBまでです: '+file.name);
   const src=await fileDataURL(file);const r=await fetch('/api/attachments',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+bridgeToken},body:JSON.stringify({name:file.name,data:src.slice(src.indexOf(',')+1)})});const a=await r.json();if(!r.ok)throw Error(a.error||'添付できません');chatAttachments.push({...a,...(a.kind==='image'?{src}: {})});
  }catch(e){toast(e.message);log('添付: '+e.message,'warn');}
 }}finally{attachmentBusy=false;if(panel==='agent')renderChatSidebar();}
}
async function removeChatAttachment(id){if(aiBusy||attachmentBusy)return;chatAttachments=chatAttachments.filter(a=>a.id!==id);renderChatSidebar();await fetch('/api/attachments/'+encodeURIComponent(id),{method:'DELETE',headers:{Authorization:'Bearer '+bridgeToken}}).catch(()=>{});}
function attachmentToAsset(id){const a=chatAttachments.find(a=>a.id===id);if(!a||a.kind!=='image')return;if(deck.assets.some(x=>x.src===a.src)){toast('この画像はすでに素材へ追加されています');return;}snapshot();deck.assets.push({id:uid(),name:a.name,type:'image',src:a.src,size:a.size});changed();toast('画像を素材へ追加しました。AIに配置を依頼できます');}
async function clearChatAttachments(){const ids=allChatAttachmentIds();chatAttachments=[];await Promise.allSettled(ids.map(id=>fetch('/api/attachments/'+encodeURIComponent(id),{method:'DELETE',headers:{Authorization:'Bearer '+bridgeToken}})));}
document.addEventListener('change',ev=>{if(ev.target.id==='chat-files')addChatFiles([...ev.target.files]);});
document.addEventListener('click',ev=>{const remove=ev.target.closest('[data-remove-chat-attachment]');if(remove)removeChatAttachment(remove.dataset.removeChatAttachment);const asset=ev.target.closest('[data-attachment-asset]');if(asset)attachmentToAsset(asset.dataset.attachmentAsset);});
// Capture file drops over the chat before the general project/media importer sees them.
