let inlineEditor=null;
function syncInlineText(session=inlineEditor){
 if(!session)return;
 const el=deck.slides.find(s=>s.id===session.slideId)?.elements?.find(e=>e.id===session.element.id);
 if(el!==session.element)return;
 const value=(session.text.childNodes?inlineDOMText(session.text):session.text.innerText).replace(/\r\n?/g,'\n');
 if(value===el.text)return;
 if(!session.historySaved){snapshot();session.historySaved=true;}
 updateTextElement(el,{text:value});changed({render:false});
 const inspector=$('[data-element-field="text"]');if(inspector&&selection.has(el.id)&&inspector!==document.activeElement)inspector.value=value;
}
function finishInlineText(){
 const session=inlineEditor;if(!session)return;syncInlineText(session);inlineEditor=null;
 session.text.removeAttribute('contenteditable');session.text.removeAttribute('role');session.text.removeAttribute('aria-label');session.text.removeAttribute('aria-multiline');session.text.classList.remove('text-editing');session.text.innerHTML=richTextHTML(session.element);$('#inline-format-toolbar')?.remove();
}
function beginInlineText(id,point,selectAll=false){
 if(presenting||isPresenter||view!=='canvas')return;
 const el=current().elements?.find(e=>e.id===id);if(el?.type!=='text'||el.locked||el.hidden)return;
 if(inlineEditor?.element===el)return;
 finishInlineText();
 const box=$('#stage').querySelector(`[data-element="${CSS.escape(id)}"]`),text=box?.querySelector('.element-text');if(!text)return;
 inlineEditor={slideId:current().id,element:el,text,historySaved:false,composing:false};
 text.contentEditable='plaintext-only';text.classList.add('text-editing');text.setAttribute('role','textbox');text.setAttribute('aria-label','スライドのテキストを編集');text.setAttribute('aria-multiline','true');text.focus({preventScroll:true});
 let range=null;
 if(point&&document.caretPositionFromPoint){const caret=document.caretPositionFromPoint(point.x,point.y);if(caret&&text.contains(caret.offsetNode)){range=document.createRange();range.setStart(caret.offsetNode,caret.offset);range.collapse(true);}}
 else if(point&&document.caretRangeFromPoint){const caret=document.caretRangeFromPoint(point.x,point.y);if(caret&&text.contains(caret.startContainer))range=caret;}
 if(!range){range=document.createRange();range.selectNodeContents(text);if(!selectAll)range.collapse(false);}
 const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);showInlineFormatToolbar();rememberInlineSelection();
}
document.addEventListener('input',ev=>{if(inlineEditor?.text.contains(ev.target))syncInlineText();});
document.addEventListener('compositionstart',ev=>{if(inlineEditor?.text.contains(ev.target))inlineEditor.composing=true;});
document.addEventListener('compositionend',ev=>{if(inlineEditor?.text.contains(ev.target)){inlineEditor.composing=false;syncInlineText();}});
document.addEventListener('focusout',ev=>{if(inlineEditor?.text===ev.target&&!ev.relatedTarget?.closest?.('#inline-format-toolbar'))finishInlineText();});
document.addEventListener('pointerdown',ev=>{if(inlineEditor&&!inlineEditor.text.contains(ev.target)&&!ev.target.closest('#inline-format-toolbar'))finishInlineText();},true);
document.addEventListener('keydown',ev=>{if(inlineEditor?.text.contains(ev.target)&&!ev.isComposing&&!inlineEditor.composing&&(ev.key==='Escape'||((ev.metaKey||ev.ctrlKey)&&ev.key==='Enter'))){ev.preventDefault();ev.stopImmediatePropagation();const text=inlineEditor.text;finishInlineText();text.blur();}},true);

actions['add-text']=()=>{const el=addElement('text');beginInlineText(el.id,null,true);};

/* Rich text is structured data, never arbitrary HTML. Plain text remains the search/export fallback. */
function validateTextRuns(e){
 if(e.textRuns===undefined)return;
 if(!Array.isArray(e.textRuns)||e.textRuns.length>10000||e.textRuns.some(r=>!r||typeof r.text!=='string'||Object.keys(r).some(k=>!['text','fontSize','bold'].includes(k))||r.fontSize!==undefined&&(!Number.isFinite(r.fontSize)||r.fontSize<1||r.fontSize>1000)||r.bold!==undefined&&typeof r.bold!=='boolean')||e.textRuns.map(r=>r.text).join('')!==e.text)throw Error('部分書式の文章・文字サイズ・太字を確認してください。');
}
function textRuns(e){return e.textRuns||[{text:e.text}];}
function mergeTextRuns(runs){const result=[];for(const r of runs){if(!r.text)continue;const last=result.at(-1);if(last&&last.fontSize===r.fontSize&&last.bold===r.bold)last.text+=r.text;else result.push({...r});}return result;}
function sliceTextRuns(runs,start,end){let offset=0;const out=[];for(const r of runs){const a=Math.max(0,start-offset),b=Math.min(r.text.length,end-offset);if(b>a)out.push({...r,text:r.text.slice(a,b)});offset+=r.text.length;}return out;}
