 // Inspector changes apply to the whole box, while the inline toolbar changes only the selection.
 if(e.textRuns&&!('textRuns'in changes))for(const key of ['fontSize','bold'])if(key in changes)e.textRuns=e.textRuns.map(r=>{const copy={...r};delete copy[key];return copy;});
